from datetime import datetime, timedelta
from typing import Dict


class _Appointment:
    def __init__(self, appointment_id: int, patient: str, doctor: str, start: datetime, end: datetime):
        self.id = appointment_id
        self.patient = patient
        self.doctor = doctor
        self.start = start
        self.end = end
        self.cancelled = False
        self.blocks_slot = True


class Scheduler:
    def __init__(self) -> None:
        self._next_id: int = 1
        self._appointments: Dict[int, _Appointment] = {}

    def book(self, patient: str, doctor: str, start: datetime, end: datetime,
             now: datetime) -> int:
        """Book an appointment; returns its id. `now` is the current time."""
        if start < now:
            raise ValueError("Cannot book an appointment that starts in the past.")

        if end <= start:
            raise ValueError("Appointment end time must be after start time.")

        if not self.is_free(doctor, start, end):
            raise ValueError(f"Doctor '{doctor}' is not available for the requested time slot.")

        appointment_id = self._next_id
        self._next_id += 1

        self._appointments[appointment_id] = _Appointment(
            appointment_id=appointment_id,
            patient=patient,
            doctor=doctor,
            start=start,
            end=end
        )
        return appointment_id

    def cancel(self, appointment_id: int, now: datetime) -> None:
        """Cancel an existing appointment."""
        if appointment_id not in self._appointments:
            raise KeyError(f"Appointment ID {appointment_id} does not exist.")

        appt = self._appointments[appointment_id]
        if appt.cancelled:
            return

        appt.cancelled = True
        # If cancelled less than 24 hours before start, the slot remains blocked.
        if (appt.start - now) < timedelta(hours=24):
            appt.blocks_slot = True
        else:
            appt.blocks_slot = False

    def is_free(self, doctor: str, start: datetime, end: datetime) -> bool:
        """True if the doctor can be booked between start and end."""
        for appt in self._appointments.values():
            if appt.doctor == doctor and appt.blocks_slot:
                # Overlap exists if max(start1, start2) < min(end1, end2)
                # Touching boundaries (e.g. start == appt.end or end == appt.start) do not overlap.
                if max(start, appt.start) < min(end, appt.end):
                    return False
        return True
